<?php require 'config.php';requireLogin('profile.php');$uid=(int)$_SESSION['user_id'];$msg='';$error='';$st=$conn->prepare('SELECT id,name,email,role,phone,shipping_address,billing_address,created_at FROM users WHERE id=?');$st->bind_param('i',$uid);$st->execute();$u=$st->get_result()->fetch_assoc();
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';if(!csrf_ok($_POST['csrf']??''))$error='Security check failed. Please refresh and try again.';elseif($action==='details'){$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$ship=trim($_POST['shipping_address']??'');$bill=trim($_POST['billing_address']??'');if($name==='')$error='Name is required.';else{$encShip=encryptField($ship);$encBill=encryptField($bill);$q=$conn->prepare('UPDATE users SET name=?,phone=?,shipping_address=?,billing_address=? WHERE id=?');$q->bind_param('ssssi',$name,$phone,$encShip,$encBill,$uid);$q->execute();$_SESSION['user_name']=$name;$msg='Profile details saved securely.'; $u['name']=$name;$u['phone']=$phone;$u['shipping_address']=$encShip;$u['billing_address']=$encBill;}}elseif($action==='password'){$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$q=$conn->prepare('SELECT password FROM users WHERE id=?');$q->bind_param('i',$uid);$q->execute();$row=$q->get_result()->fetch_assoc();if(!$row||!password_verify($current,$row['password']))$error='Current password is incorrect.';elseif(!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/',$new))$error='New password must be 8+ characters with uppercase, lowercase and a number.';elseif($new!==$confirm)$error='New passwords do not match.';else{$hash=password_hash($new,PASSWORD_BCRYPT);$q=$conn->prepare('UPDATE users SET password=? WHERE id=?');$q->bind_param('si',$hash,$uid);$q->execute();$msg='Password changed successfully.';}}}
$pageTitle='My Profile | Ceylon Noir';require 'header.php';?><section class="profile-page"><div class="profile-head"><div class="avatar"><?php echo e(strtoupper(substr($u['name'],0,1)));?></div><div><span class="gold-kicker">MEMBER PROFILE</span><h1><?php echo e($u['name']);?></h1><p class="muted"><?php echo e($u['email']);?> · Status: <strong class="gold-text">Active Member</strong></p></div></div><?php if($msg):?><div class="success"><?php echo e($msg);?></div><?php endif;?><?php if($error):?><div class="alert"><?php echo e($error);?></div><?php endif;?><div class="profile-grid"><div class="panel"><h2>Account Details</h2><form method="post"><input type="hidden" name="csrf" value="<?php echo e(csrf_token());?>"><input type="hidden" name="action" value="details"><label>Full Name</label><input name="name" value="<?php echo e($u['name']);?>" required><label>Email</label><input value="<?php echo e($u['email']);?>" disabled><label>Phone</label><input name="phone" value="<?php echo e($u['phone']);?>"><label>Shipping Address</label><textarea name="shipping_address" rows="4"><?php echo e(decryptField($u['shipping_address']));?></textarea><label>Billing Address</label><textarea name="billing_address" rows="4"><?php echo e(decryptField($u['billing_address']));?></textarea><button class="gold-btn" type="submit">SAVE DETAILS</button></form></div><div><div class="panel"><h2>Membership</h2><p>Role: <strong class="gold-text"><?php echo e(ucfirst($u['role']));?></strong></p><p>Registered: <?php echo e(date('d M Y',strtotime($u['created_at'])));?></p><p>Cart state: <?php echo cartCount();?> item(s) currently saved.</p></div><div class="panel"><h2>Change Password</h2><form method="post"><input type="hidden" name="csrf" value="<?php echo e(csrf_token());?>"><input type="hidden" name="action" value="password"><label>Current Password</label><input type="password" name="current_password" required><label>New Password</label><input type="password" name="new_password" minlength="8" required><label>Confirm New Password</label><input type="password" name="confirm_password" minlength="8" required><button class="gold-btn" type="submit">CHANGE PASSWORD</button></form></div></div></div></section><?php require 'footer.php';?>
